/* ---------- screen: how the app works (from the home screen) ----------
   Where the data comes from, the tables of data.js drawn as cards (what one row is, its row count, its links, one real row,
   every column and where it comes from), and what the gate checks. All of it is read when the screen is drawn: the counts and
   rows from the tables (D), each table's columns and their sources from verify/columns.json as the gate that checked this
   build wrote it into verified.js (VER.tables), the checks from verified.js. verify/render.js compares the screen with data.js. */
const HOW_TITLE = 'How the app works and why you should be able to trust the data';
// the tables of data.js, in the order the screen draws them: name, key in D, what one row is (verify/columns.json says it for most)
const HW_TABLES = [['ARMIES', 'armies'], ['DATASHEETS', 'datasheets'], ['FACTIONS', 'factions'], ['CORE_STRATAGEMS', 'coreStratagems'], ['RULES', 'rules'],
  ['RULE_ALIASES', 'ruleAliases'], ['RULE_SRC', 'ruleSrc'], ['CONCEPTS', 'concepts'], ['GRANTS', 'grants'], ['RULE_OPTIONS', 'ruleOptions'],
  ['CHECKLIST', 'checklist'], ['BS_IDS', 'bsIds'], ['VERSION', 'version']];
const HW_WHAT = { CHECKLIST:'per rule and ability, where the Phase checklist lists it: worked out from its words by verify/derive.js',
  VERSION:'the data’s version: one value, raised with every release' };
// CHECKLIST's columns (verify/derive.js writes them; verify/render.js fails on one this does not name)
const HW_CK = { t:'the phases it is triggered in', u:'the phases its effect is used in', s:'listed at a fixed moment of the turn', a:'listed when the unit is selected',
  at:'the moment it opens with', ae:'also at the end of the battle round', o:'its options, each with its own phases', g:'what it grants', f:'a rule it puts in force',
  pk:'a pick of options', oc:'its options cover its phases', x:'not placed (its words give no phase)', none:'no phase (before the battle, what a unit carries)' };
const HW_SRC = { gw:'GW', bsdata:'BSData', newrecruit:'New Recruit', wahapedia:'Wahapedia', derived:'computed' };
const HW_LAYERS = [
  ['mech', 'Mechanical', 'copied by a program from GW, BSData, New Recruit or Wahapedia, or worked out from them by a program; the tag names the source.'],
  ['sum', 'AI summary', 'a one-line gist of a stratagem, written by AI. It carries a fingerprint of the text it sums up: a change in GW’s words flags it to be read again.'],
  ['read', 'AI reading', 'the numbers and conditions the Damage tab and the Phase checklist use, read from GW’s words by AI: fingerprinted, and each signed off by an independent reviewer.'],
  ['hand', 'Hand', 'a decision written by hand: which source wins where they disagree (GW), ids, aliases, notes; signed off by a reviewer.']];
// a column's layer, from its source in verify/columns.json
const hwLayer = (t, col, src) => src === 'ai' ? (col === 'def' ? 'read' : 'sum')
  : src !== 'hand' ? 'mech'
  : /\.(mods|aura|guard|readings)$/.test(t) || /^(mods|aura|guard|mod|def)$|^calc|^def[A-Z]|Calc$/.test(col) ? 'read' : 'hand';
const hwCols = t => { const x = VER && VER.tables && VER.tables[t]; return x ? x.cols.split(' ').filter(Boolean).map(c => { const i = c.indexOf(':'); return [c.slice(0, i), c.slice(i + 1)]; }) : null; };
const hwTag = (t, col, src) => { if(!src) return ''; const l = hwLayer(t, col, src);
  return '<span class="ly ' + l + '">' + esc(l === 'mech' ? HW_SRC[src] || src : HW_LAYERS.find(x => x[0] === l)[1]) + '</span>'; };
const hwRows = k => { const v = D[k]; return Array.isArray(v) ? v.length : isObj(v) ? Object.keys(v).length : 1; };
const hwN = (n, one, many) => n + ' ' + (n === 1 ? one : many);
// the rows of an inner table, in all (null: rows the screen does not count, the list's own rows, a rule's readings)
function hwSubRows(t){
  const p = t.split('.'), root = { ARMIES:D.armies, DATASHEETS:Object.values(D.datasheets), FACTIONS:Object.values(D.factions) }[p[0]];
  if(!root || /\.readings$/.test(t) || (p[0] === 'ARMIES' && p.length > 2)) return null;
  let xs = root;
  for(const k of p.slice(1)) xs = xs.flatMap(x => { const v = k === 'units' ? unitsAll(x) : x[k]; return v == null ? [] : Array.isArray(v) ? v : k === 'detachments' ? Object.values(v) : [v]; });
  return xs.length;
}
const hwPlain = s => String(s).replace(/\*\*|~~/g, '').replace(/\s+/g, ' ').trim();
const hwCut = s => s.length > 110 ? s.slice(0, 108).replace(/\s+\S*$/, '') + ' …' : s;
const hwFlat = x => x instanceof RegExp ? String(x) : Array.isArray(x) ? x.map(hwFlat).join(', ') : isObj(x) ? Object.entries(x).map(([k, v]) => k + ': ' + hwFlat(v)).join('; ') : String(x);
function hwVal(v){
  if(v == null) return '–';
  if(v instanceof RegExp) return String(v);
  if(Array.isArray(v) && v.length && v.every(isObj)) return hwN(v.length, 'row', 'rows') + (v.every(x => x.name) ? ': ' + v.map(x => x.name).join(', ') : '');
  if(Array.isArray(v)) return v.map(x => Array.isArray(x) ? '[' + hwFlat(x) + ']' : hwFlat(x)).join(' · ');
  if(isObj(v) && typeof v.name === 'string') return v.name + (Object.keys(v).length > 1 ? ' (+ ' + hwN(Object.keys(v).length - 1, 'column', 'columns') + ')' : '');
  return hwFlat(v);
}
// one row as a small table: each column, its value and its layer
const hwLine = (k, html, tag) => '<div class="pgr"><span class="pgk">' + esc(k) + '</span><span class="pgv"><span>' + html + '</span>' + (tag || '') + '</span></div>';
function hwRow(t, pairs){
  const src = new Map(hwCols(t) || []);
  return '<div class="pg hwx">' + pairs.map(([k, v]) => hwLine(k, esc(hwCut(hwPlain(hwVal(v)))), hwTag(t, k, src.get(k)))).join('') + '</div>';
}
// a row's columns in the order verify/columns.json lists them, then any it does not
const hwPairs = (t, o) => { const cols = (hwCols(t) || []).map(c => c[0]).filter(c => hasOwn(o, c)); return cols.concat(Object.keys(o).filter(k => !cols.includes(k))).map(k => [k, o[k]]); };
// every column of a table and its inner tables, by layer
function hwColumns(t){
  const subs = VER && VER.tables ? Object.keys(VER.tables).filter(k => k.startsWith(t + '.')) : [];
  const block = k => { const cols = hwCols(k); if(!cols) return '';
    const n = k === t ? hwRows(HW_TABLES.find(x => x[0] === t)[1]) : hwSubRows(k);
    return '<div class="hwct" data-t="' + esc(k) + '" data-cols="' + esc(cols.map(c => c[0]).join(',')) + '"><b>' + esc(k) + '</b>' + (n == null ? '' : ' <span class="hwn">' + hwN(n, 'row', 'rows') + '</span>') +
      (k === t ? '' : '<p class="hww">' + esc(VER.tables[k].what) + '</p>') +
      HW_LAYERS.map(([l, name]) => { const these = cols.filter(([c, s]) => hwLayer(k, c, s) === l); if(!these.length) return '';
        return '<p class="hwl"><span class="ly ' + l + '">' + name + '</span> ' + these.map(([c, s]) => esc(c) + (l === 'mech' ? ' <span class="hws">(' + esc(HW_SRC[s] || s) + ')</span>' : '')).join(', ') + '</p>'; }).join('') + '</div>'; };
  const all = [t].concat(subs), n = all.reduce((x, k) => x + (hwCols(k) || []).length, 0);
  if(!n) return '';
  return '<details class="xp"><summary><span class="xh"><b>Every column and where it comes from</b><span>' + hwN(n, 'column', 'columns') + (subs.length ? ', with ' + hwN(subs.length, 'inner table', 'inner tables') : '') + '</span></span>' + chev + '</summary>' +
    '<div class="body">' + all.map(block).join('') + '</div></details>';
}
// a link to another table's card
const hwTo = t => '<button class="link" data-htab="' + t + '">' + t + '</button>';
const hwKey = (k, html) => '<p class="hwk"><span class="il">' + esc(k) + '</span>' + html + '</p>';
// the example: one list (the owner's first, else the first), its first unit with a datasheet of its own, that datasheet's id
function hwExample(){
  const a = armyById('shooty') || D.armies[0], ids = Object.keys(D.datasheets);
  for(const u of a.units){ const ds = ids.find(k => D.datasheets[k].faction === a.faction && D.datasheets[k].name === u.name); if(ds) return { a, u, ds }; }
  return { a, u:a.units[0], ds:null };
}
// where a GRANTS or RULE_OPTIONS row's rule is: an army rule, a detachment rule (FACTIONS) or a unit's ability (a list's datasheet)
const hwRuleAt = r => { const p = r.split(' · '); return p.length === 2 ? 'army' : / rule$/.test(p[1]) ? 'det' : 'ability'; };
function hwRuleLinks(rows){
  const n = k => rows.filter(x => hwRuleAt(x.rule) === k).length;
  return hwKey('rule', '→ an army rule (' + n('army') + ') or detachment rule (' + n('det') + ') in ' + hwTo('FACTIONS') + ', or a unit’s ability (' + n('ability') + ') in a list (' + hwTo('ARMIES') + ' → ' + hwTo('DATASHEETS') + ')');
}
function hwCard(t, k){
  const X = hwExample(), a = X.a, u = X.u, f = D.factions[a.faction], rows = hwRows(k);
  const what = (VER && VER.tables && VER.tables[t] && VER.tables[t].what) || HW_WHAT[t] || '';
  let body = '', count = hwN(rows, 'row', 'rows');
  const ex = (label, html) => '<p class="lbl hwe">' + label + '</p>' + html;
  if(t === 'ARMIES'){
    const entries = D.armies.reduce((n, x) => n + unitsAll(x).length, 0);
    count += ' · ' + hwN(entries, 'unit entry', 'unit entries');
    body = hwKey('units[ ].ds', '→ the unit’s ' + hwTo('DATASHEETS') + ' row') + hwKey('faction, detachments', '→ ' + hwTo('FACTIONS') + ' and its detachments') +
      ex('One row: ' + esc(a.name), hwRow(t, hwPairs(t, a).filter(([c]) => c !== 'refs').map(([c, v]) => [c, c === 'units' ? hwN(unitsAll(a).length, 'entry', 'entries') : v]))) +
      ex('One of its unit entries', '<div data-hwentry="' + esc(a.id + '|' + u.id) + '">' + hwRow('ARMIES.units', [['id', u.id], ['ds', X.ds]].concat(['short', 'pts', 'enhancement', 'warlord', 'models', 'gear'].filter(c => u[c] != null).map(c => [c, u[c]]))) + '</div>') +
      '<p class="note">An entry holds what the list chose; everything else about the unit comes from its datasheet’s row.</p>';
  }
  else if(t === 'DATASHEETS'){
    const ds = X.ds && D.datasheets[X.ds];
    body = hwKey('key', '“faction/name”, the id an entry’s ds names') + hwKey('rules', '→ by name: a core rule in ' + hwTo('RULES') + ' (through ' + hwTo('RULE_ALIASES') + ') or an army rule in ' + hwTo('FACTIONS')) +
      (ds ? ex('One row: ' + esc(X.ds), hwRow(t, hwPairs(t, ds))) : '');
  }
  else if(t === 'FACTIONS'){
    const dets = Object.values(f.detachments), det = f.detachments[a.detachments[0]] || dets[0];
    body = hwKey('key', 'the faction’s id, the faction an army names') + hwKey('detachments', '→ each with its rule, stratagems and enhancements, inside the row') +
      ex('One row: ' + esc(a.faction), hwRow(t, hwPairs(t, f).map(([c, v]) => [c, c === 'detachments' ? hwN(dets.length, 'detachment', 'detachments') + ': ' + dets.map(d => d.name).join(', ') : v]))) +
      (det ? ex('One of its detachments', hwRow('FACTIONS.detachments', hwPairs('FACTIONS.detachments', det))) : '') +
      (det && det.stratagems && det.stratagems[0] ? ex('One of its stratagems', hwRow('FACTIONS.detachments.stratagems', hwPairs('FACTIONS.detachments.stratagems', det.stratagems[0]))) : '');
  }
  else if(t === 'CORE_STRATAGEMS') body = hwKey('used by', 'every list') + ex('One row', hwRow(t, hwPairs(t, D.coreStratagems[0])));
  else if(t === 'RULES'){ const r = (u.rules || []).find(x => hasOwn(D.rules, x)) || Object.keys(D.rules)[0];
    body = hwKey('key', 'the rule’s name') + ex('One row', hwRow(t, [['name', r], ['text', D.rules[r]]])); }
  else if(t === 'RULE_ALIASES') body = hwKey('rule', '→ ' + hwTo('RULES')) + ex('One row', hwRow(t, [['pattern', D.ruleAliases[0][0]], ['rule', D.ruleAliases[0][1]]]));
  else if(t === 'RULE_SRC'){ const r = Object.keys(D.ruleSrc)[0]; body = hwKey('name', '→ ' + hwTo('RULES')) + ex('One row', hwRow(t, [['name', r], ['source', D.ruleSrc[r]]])); }
  else if(t === 'CONCEPTS') body = ex('Its rows', '<p class="hwk">' + D.concepts.map(esc).join(' · ') + '</p>');
  else if(t === 'GRANTS' || t === 'RULE_OPTIONS'){ const list = D[k], r = list.find(x => x.rule.startsWith(f.name + ' ')) || list[0];
    body = hwRuleLinks(list) + ex('One row', hwRow(t, hwPairs(t, r))); }
  else if(t === 'CHECKLIST'){
    const keys = Object.keys(D.checklist), nA = keys.filter(x => x.startsWith('a|')).length, nR = keys.filter(x => x.startsWith('r|')).length;
    const ab = (u.abilities || []).find(x => D.checklist['a|' + ckHash(x.name + '\n' + x.text)]), kk = ab ? 'a|' + ckHash(ab.name + '\n' + ab.text) : keys[0], e = D.checklist[kk];
    body = hwKey('r|faction|name', '→ an army or detachment rule in ' + hwTo('FACTIONS') + ' (' + nR + ')') + hwKey('a|fingerprint', '→ an ability, by a fingerprint of its name and words (' + nA + '), in ' + hwTo('DATASHEETS')) +
      ex('One row' + (ab ? ': ' + esc(ab.name) + ' (' + esc(u.name) + ')' : ''), '<div class="pg hwx">' + hwLine('key', esc(kk), '<span class="ly mech">computed</span>') +
        Object.keys(e).map(c => hwLine(c, esc(hwCut(hwPlain(hwVal(e[c])))) + ' <span class="hws">(' + esc(HW_CK[c] || '') + ')</span>', '<span class="ly mech">computed</span>')).join('') + '</div>') +
      '<p class="hwl">' + Object.keys(HW_CK).filter(c => keys.some(x => hasOwn(D.checklist[x], c))).map(c => '<b>' + esc(c) + '</b> ' + esc(HW_CK[c])).join(' · ') + '</p>';
  }
  else if(t === 'BS_IDS'){ count = hwN(rows, 'lookup', 'lookups');
    body = hwKey('used by', 'the list import, to find each unit and choice of a New Recruit export') +
      ex('Its lookups', hwRow(t, Object.keys(D.bsIds).map(c => [c, (v => Array.isArray(v) ? hwN(v.length, 'id', 'ids') : isObj(v) ? hwN(Object.keys(v).length, 'id', 'ids') : v)(D.bsIds[c])]))); }
  else if(t === 'VERSION'){ count = 'one value'; body = ex('Its value', '<p class="hwk">' + esc(D.version) + '</p>'); }
  return '<div class="hwc" id="sec-hw-' + t + '" data-table="' + t + '" data-rows="' + rows + '"><div class="hwh"><b>' + t + '</b><span class="c">' + count + '</span></div>' +
    (what ? '<p class="hww">' + esc(what) + '</p>' : '') + body + hwColumns(t) + '</div>';
}
// the map: the tables as boxes, their links as arrows (one row count each, from the tables)
function hwMap(){
  const n = t => hwRows(HW_TABLES.find(x => x[0] === t)[1]), dets = Object.values(D.factions).flatMap(f => Object.values(f.detachments));
  const sum = (xs, k) => xs.reduce((x, d) => x + (d[k] || []).length, 0);
  const box = (t, x, y, w, h, sub) => '<rect x="' + x + '" y="' + y + '" width="' + w + '" height="' + h + '" rx="4"/><text class="t" x="' + (x + 8) + '" y="' + (y + 17) + '">' + t + '</text>' +
    (sub ? '<text class="s" x="' + (x + 8) + '" y="' + (y + 32) + '">' + esc(sub) + '</text>' : '');
  const one = (t, x, y, w) => '<rect x="' + x + '" y="' + y + '" width="' + w + '" height="28" rx="4"/><text class="t" x="' + (x + 8) + '" y="' + (y + 18) + '">' + t + ' <tspan class="s">' + n(t) + '</tspan></text>';
  const ar = d => '<path class="ar" d="' + d + '" marker-end="url(#hwa)"/>';
  const lab = (x, y, s, mid) => '<text class="k" x="' + x + '" y="' + y + '"' + (mid ? ' text-anchor="middle"' : '') + '>' + esc(s) + '</text>';
  const entries = D.armies.reduce((x, a) => x + unitsAll(a).length, 0);
  return '<figure class="hwmap"><svg viewBox="0 0 320 366" role="img" aria-label="How the tables link: an army’s unit entries name their DATASHEETS row (ds) and the army names its FACTIONS row; datasheets name their core rules in RULES; RULE_ALIASES and RULE_SRC point at RULES; GRANTS, RULE_OPTIONS and CHECKLIST point at a rule in FACTIONS or an ability of a datasheet; CORE_STRATAGEMS serve every list; BS_IDS serve the list import.">' +
    '<defs><marker id="hwa" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0 0L8 4L0 8z"/></marker></defs>' +
    box('ARMIES', 8, 8, 128, 44, hwN(D.armies.length, 'list', 'lists') + ' · ' + entries + ' entries') +
    box('FACTIONS', 184, 8, 128, 110, hwN(n('FACTIONS'), 'row', 'rows')) +
    '<text class="s" x="192" y="60">army rules ' + sum(Object.values(D.factions), 'armyRules') + '</text><text class="s" x="192" y="76">detachments ' + dets.length + '</text>' +
    '<text class="s" x="200" y="92">↳ stratagems ' + sum(dets, 'stratagems') + '</text><text class="s" x="200" y="108">↳ enhancements ' + sum(dets, 'enhancements') + '</text>' +
    ar('M136 30H182') + lab(160, 25, 'faction', true) +
    box('DATASHEETS', 8, 86, 128, 44, hwN(n('DATASHEETS'), 'row', 'rows')) + ar('M72 52V84') + lab(78, 72, 'ds') +
    box('RULES', 8, 170, 128, 44, hwN(n('RULES'), 'row', 'rows')) + ar('M72 130V168') + lab(78, 153, 'rules') +
    one('RULE_ALIASES', 184, 134, 128) + one('RULE_SRC', 184, 168, 128) + one('CONCEPTS', 184, 202, 128) +
    ar('M184 148L138 184') + ar('M184 182L138 196') +
    one('GRANTS', 8, 264, 96) + one('RULE_OPTIONS', 112, 264, 96) + one('CHECKLIST', 216, 264, 96) +
    '<path class="ar" d="M56 264V250H264V264M160 250V264"/>' + ar('M56 250H3V108H6') + ar('M264 250H317V40H314') + lab(160, 244, 'rule / key → a rule or an ability', true) +
    box('CORE_STRATAGEMS', 8, 314, 128, 44, n('CORE_STRATAGEMS') + ' · used by every list') + box('BS_IDS', 184, 314, 128, 44, n('BS_IDS') + ' lookups · import') +
    '</svg></figure>';
}
function screenHow(){
  const steps = [
    ['Where the data comes from', 'Your New Recruit lists; BSData, the data New Recruit is built from; Games Workshop’s Core Rules, Faction Packs and FAQs, and Wahapedia where GW has no document yet. Where they disagree, GW wins.'],
    ['How a list is built', 'A program reads the list and writes it into the tables: each unit an entry that points at its datasheet, its stats, weapons, keywords, points and rules text copied from the sources.'],
    ['The tables', 'Everything the app shows is in ' + HW_TABLES.length + ' tables in one file, data.js, drawn below with their real columns and row counts. Each column is tagged: mechanical, AI-written or decided by hand.'],
    ['What checks every release', 'A second program compares every table with its sources again and renders every screen; if a single check fails, nothing is released. <button class="link" data-htab="trust">What it checks</button>'],
    ['How the app draws pages', 'One page template reads the tables and draws every screen from them. Each release renders every screen of every list and compares its text with the last one accepted, so no screen changes unseen.']];
  const all = VER && VER.tables ? Object.keys(VER.tables).flatMap(t => hwCols(t).map(([c, s]) => hwLayer(t, c, s))) : [];
  const share = all.length ? '<p class="note">Of the ' + all.length + ' columns of the tables: ' + HW_LAYERS.map(([l, name]) => name + ' ' + all.filter(x => x === l).length).join(' · ') + '.</p>' : '';
  return '<p class="hwi">Where every line of this app comes from, the tables it is kept in, and what is checked before any change reaches your phone.</p>' +
    '<ol class="hwflow">' + steps.map(([h, t], i) => '<li><b>' + (i + 1) + ' · ' + h + '</b><span>' + t + '</span></li>').join('') + '</ol>' +
    '<div class="sec-h"><h2>The tables</h2><span class="c">' + HW_TABLES.length + '</span></div>' + hwMap() +
    '<div class="hwleg">' + HW_LAYERS.map(([l, name, t]) => '<p class="vchk"><span class="ly ' + l + '">' + name + '</span> ' + esc(t) + '</p>').join('') + '</div>' + share +
    HW_TABLES.map(([t, k]) => hwCard(t, k)).join('') +
    '<div class="sec-h" id="sec-hw-trust"><h2>Why you can trust the data</h2></div>' +
    '<p class="hwp">Games Workshop is the source of truth. Where New Recruit, BSData or Wahapedia say something else, the difference is written down with its reason, and every release checks it again.</p>' +
    '<p class="hwp">What AI wrote is marked on the tables above: summaries and readings. Each carries a fingerprint of the rule text it was written from, so a change in GW’s words flags it, and every judgement the app adds is signed off by an independent reviewer; a changed rule voids its sign-off.</p>' +
    '<p class="hwp">Nothing ships unless every check passes: the build refuses to run otherwise.</p>' +
    (VER ? '<p class="qh">Checked ' + esc(VER.date) + '</p>' + VER.checks.map(c => '<p class="vchk"><b>' + esc(c.label) + '</b> ' + esc(c.detail) + '</p>').join('') +
      '<details class="xp"><summary><span class="xh"><b>Sources</b><span>what it was compared with</span></span>' + chev + '</summary><div class="body">' + VER.sources.map(c => '<p class="vchk"><b>' + esc(c.label) + '</b> ' + esc(c.detail) + '</p>').join('') + '</div></details>'
      : '<p class="note">This copy carries no record of its check.</p>');
}

const calm = c => c.s === 'home' || isFolder(c.s) || c.s === 'how' || c.s === 'army' || c.s === 'settings';   // screens where an update reload loses nothing

function parentOf(c){
  if(c.s === 'unit') return { s:'units', army:c.army };
  if(c.s === 'home') return null;
  if(isFolder(c.s) || c.s === 'how') return { s:'home' };
  if(c.s === 'settings') return c.army ? { s:'army', army:c.army } : { s:'home' };
  if(isTab(c.s)) return ONLY ? null : { s:'home' };
  if(c.s === 'bases') return { s:'pregame', army:c.army };
  return { s:'army', army:c.army };

function titleOf(c){
  if(c.s === 'home') return 'Armies';
  if(isFolder(c.s)) return FOLDER_TITLE[c.s];
  if(c.s === 'how') return 'How the app works';
  if(c.s === 'settings') return 'Settings';
  if(c.s === 'strats') return 'Stratagems';
  if(c.s === 'army') return (armyById(c.army) || {}).name || '';
  if(c.s === 'unit') return (unitsAll(armyById(c.army) || { units:[] }).find(u => u.id === c.unit) || {}).name || '';
  return SCREEN_TITLE[c.s] || '';

function valid(c){
  if(!c || !c.s) return false;
  if(c.s === 'home' || isFolder(c.s) || c.s === 'how') return true;
  if(c.s === 'settings') return !c.army || !!armyById(c.army);
  const a = armyById(c.army);
  if(!a) return false;
  if(c.s === 'unit') return unitsAll(a).some(u => u.id === c.unit);
  return c.s === 'army' || hasOwn(SCREEN_TITLE, c.s);

function screenHome(){
  const row = (s, ic, n) => '<button class="row" data-folder="' + s + '"><svg class="ic" aria-hidden="true"><use href="#' + ic + '"/></svg><span class="rb"><b>' + FOLDER_TITLE[s] + '</b></span>' +
    '<span class="c">' + n + '</span>' + arrow + '</button>';
  return '<div class="hlh"><div class="lbl grp-h">Your armies</div></div><div class="list">' + row('favs', 'i-star', favLists().length) + row('lists', 'i-folder', D.armies.length) + '</div>' +
    importRow() + '<div class="list hwrow"><button class="row" data-how><svg class="ic" aria-hidden="true"><use href="#i-checks"/></svg><span class="rb"><b>' + HOW_TITLE + '</b></span>' + arrow + '</button></div>' +
    verifiedLine() + (INSTALLED ? '' : '<p class="note">' + installText() + '</p>');

  if(el.hasAttribute('data-how')){ go({ s:'how' }); return; }
  if(ds.htab){ jumpTo('hw-' + ds.htab); return; }   // How the app works: a table's card, or the checks

  // ---- How the app works (from the home screen) ----
  // - how-row: home has the row "How the app works and why you should be able to trust the data"; it opens the screen, which comes back
  //   on a reload with its Back, and Back returns home
  // - how-tables: every table of data.js (TABLE_ORDER aside: the key order verify/tables.js writes, which the app never gets) has its card,
  //   with its real row count (and ARMIES its unit entries); every table of verify/columns.json has its columns, as columns.json lists them
  // - how-example: the unit entry shown is the one data.js stores (its ds and every field shown, as data.js has them)
  // - how-links: every GRANTS and RULE_OPTIONS row's rule is where the card says (an army rule, a detachment rule, a list's unit's ability);
  //   every CHECKLIST column is explained
  const howChecks = async () => {
    const src = fs.readFileSync(path.join(ROOT, 'data.js'), 'utf8'), names = [...src.matchAll(/^const ([A-Z_]+) = /gm)].map(m => m[1]).filter(n => n !== 'TABLE_ORDER');
    const RAW = (() => { const t = src.replace(/\nreturn \{ version:VERSION/, '\nreturn { __raw:{ ' + names.join(', ') + ' }, version:VERSION'); if(t === src) return null;
      const w = {}; new Function('window', t)(w); return w.WH_DATA.__raw; })();
    if(!RAW){ fail('how-tables', '', 'data.js', 'its return line was not found: the raw tables could not be read'); return; }
    const rows = v => Array.isArray(v) ? v.length : v && typeof v === 'object' ? Object.keys(v).length : 1;
    const COLS = JSON.parse(fs.readFileSync(path.join(ROOT, 'verify/columns.json'), 'utf8')).tables;
    await page.evaluate(() => { hideSheet(); go({ s:'home' }); });
    await page.waitForTimeout(400);
    const label = await page.evaluate(() => { const b = document.querySelector('#view [data-how]'); return b ? b.innerText.trim() : null; });
    if(label !== 'How the app works and why you should be able to trust the data') fail('how-row', '', 'home', JSON.stringify(label));
    if(label){ await page.click('#view [data-how]'); await page.waitForTimeout(300); }
    const o = await page.evaluate(() => ({ s:cur.s, t:$('#top').innerText, back:($('#top [data-back]') || {}).textContent || '' }));
    if(o.s !== 'how' || !/How the app works/.test(o.t) || o.back !== 'Armies') fail('how-row', '', 'the row opens it', JSON.stringify(o));
    const got = await page.evaluate(() => ({ cards:[...document.querySelectorAll('#view .hwc')].map(c => ({ t:c.dataset.table, rows:+c.dataset.rows, head:c.querySelector('.hwh .c').textContent })),
      cols:Object.fromEntries([...document.querySelectorAll('#view .hwct')].map(x => [x.dataset.t, x.dataset.cols])) }));
    for(const n of names){ const c = got.cards.find(x => x.t === n), want = rows(RAW[n]);
      if(!c) fail('how-tables', '', n, 'no card'); else if(c.rows !== want || !(n === 'VERSION' ? c.head === 'one value' : c.head.startsWith(want + ' '))) fail('how-tables', '', n, 'shows ' + c.rows + ' (' + c.head + '), data.js has ' + want); }
    for(const c of got.cards) if(!names.includes(c.t)) fail('how-tables', '', c.t, 'a card for a table data.js does not have');
    const entries = RAW.ARMIES.reduce((x, a) => x + a.units.length, 0), ac = got.cards.find(x => x.t === 'ARMIES');
    if(ac && !ac.head.includes(entries + ' unit entries')) fail('how-tables', '', 'ARMIES', 'unit entries: ' + ac.head + ', data.js has ' + entries);
    for(const t of Object.keys(COLS)){ const want = Object.keys(COLS[t].columns || {}).join(','); if(got.cols[t] !== want) fail('how-tables', '', t, 'columns ' + got.cols[t] + ', columns.json ' + want); }
    for(const t of Object.keys(got.cols)) if(!COLS[t]) fail('how-tables', '', t, 'columns of a table columns.json does not have');
    const ex = await page.evaluate(() => { const el = document.querySelector('#view [data-hwentry]'); return el && { at:el.dataset.hwentry, rows:[...el.querySelectorAll('.pgr')].map(r => [r.querySelector('.pgk').textContent, r.querySelector('.pgv > span').textContent]) }; });
    if(!ex) fail('how-example', '', 'ARMIES', 'no unit entry shown');
    else { const [aid, uid] = ex.at.split('|'), e = ((RAW.ARMIES.find(x => x.id === aid) || { units:[] }).units.find(x => x.id === uid));
      if(!e) fail('how-example', '', ex.at, 'not an entry of data.js');
      else { const want = await page.evaluate(e => Object.fromEntries(Object.keys(e).map(k => [k, hwCut(hwPlain(hwVal(e[k])))])), e);
        for(const [k, v] of ex.rows) if(want[k] !== v) fail('how-example', '', ex.at + ' ' + k, 'shows ' + JSON.stringify(v) + ', data.js has ' + JSON.stringify(want[k])); } }
    const ln = await page.evaluate(() => {
      const fac = n => Object.values(D.factions).find(f => f.name === n);
      const at = r => { const p = r.split(' · '), k = hwRuleAt(r);
        if(k === 'army'){ const f = fac(p[0].replace(/ army rule$/, '')); return !!f && f.armyRules.some(x => x.name === p[1]); }
        if(k === 'det'){ const f = fac(p[0]); return !!f && Object.values(f.detachments).some(d => d.name + ' rule' === p[1]); }
        const a = armyById(p[0]); return !!a && unitsAll(a).some(u => u.name === p[1] && u.abilities.some(x => x.name === p[2])); };
      return { bad:D.grants.concat(D.ruleOptions).filter(x => !at(x.rule)).map(x => x.rule),
        ck:[...new Set(Object.values(D.checklist).flatMap(Object.keys))].filter(c => !hasOwn(HW_CK, c)) }; });
    if(ln.bad.length) fail('how-links', '', 'GRANTS / RULE_OPTIONS', 'a rule not where the card says: ' + ln.bad.slice(0, 5).join('; '));
    if(ln.ck.length) fail('how-links', '', 'CHECKLIST', 'columns the card does not explain: ' + ln.ck.join(', '));
    await page.reload(); await page.evaluate(() => document.fonts.ready); await page.waitForTimeout(300);
    const re = await page.evaluate(() => ({ s:cur.s, back:($('#top [data-back]') || {}).textContent || '' }));
    if(re.s !== 'how' || re.back !== 'Armies') fail('how-row', '', 'reload on How the app works', JSON.stringify(re));
    if(re.back){ await page.click('#top [data-back]'); await page.waitForTimeout(300); }
    const hb = await page.evaluate(() => cur.s);
    if(hb !== 'home') fail('how-row', '', 'Back', hb);
  };

// verify/columns.json in short, { table: { what, cols:'column:source …' } }: verified.js carries it for the app's "How the app works"
// screen (each table's columns and where each comes from), so the screen shows what the gate that wrote it checked
const columnSources = () => Object.fromEntries(Object.entries(readJSON(path.join(ROOT, 'verify/columns.json'), {}).tables || {})
  .map(([t, v]) => [t, { what:v.what || '', cols:Object.entries(v.columns || {}).map(([n, x]) => n + ':' + x.source).join(' ') }]));
